import{_ as t,o as h,c as a,a3 as i}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/bat-dau/dang-nhap.png",m=JSON.parse('{"title":"Đăng nhập & Mật khẩu","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/dang-nhap.md","filePath":"bat-dau/dang-nhap.md","lastUpdated":1781610463000}'),l={name:"bat-dau/dang-nhap.md"};function g(r,n,u,s,c,e){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="đang-nhap-mat-khau" tabindex="-1">Đăng nhập &amp; Mật khẩu <a class="header-anchor" href="#đang-nhap-mat-khau" aria-label="Permalink to &quot;Đăng nhập &amp; Mật khẩu&quot;">​</a></h1><p>Hướng dẫn đăng nhập vào FADO AssetFlow, đăng xuất, và xử lý khi quên mật khẩu.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>https://assetflow.fadoai.com/sign-up-login-screen</code></li><li><strong>Ai dùng được:</strong> Tất cả người dùng có tài khoản trong hệ thống.</li><li><strong>Liên quan:</strong> Quên mật khẩu · Đặt lại mật khẩu qua email · Đăng xuất.</li></ul></div><h2 id="giao-dien-đang-nhap" tabindex="-1">Giao diện đăng nhập <a class="header-anchor" href="#giao-dien-đang-nhap" aria-label="Permalink to &quot;Giao diện đăng nhập&quot;">​</a></h2><p><img src="'+o+'" alt="Màn hình đăng nhập"></p><p>Form đăng nhập gồm các trường:</p><ul><li><strong>Email đăng nhập</strong> — email tài khoản của bạn (ví dụ <code>your.email@company.vn</code>).</li><li><strong>Mật khẩu</strong> — có nút con mắt để hiện/ẩn mật khẩu.</li><li><strong>Ghi nhớ đăng nhập</strong> — ô tích để duy trì phiên đăng nhập.</li></ul><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="đang-nhap" tabindex="-1">Đăng nhập <a class="header-anchor" href="#đang-nhap" aria-label="Permalink to &quot;Đăng nhập&quot;">​</a></h3><ol><li>Truy cập <code>https://assetflow.fadoai.com</code>.</li><li>Nhập <strong>Email đăng nhập</strong> và <strong>Mật khẩu</strong>.</li><li>(Tùy chọn) Tích <strong>Ghi nhớ đăng nhập</strong>.</li><li>Nhấn nút <strong>Đăng Nhập</strong>.</li><li>Sau khi xác thực thành công, hệ thống hiển thị màn hình chào mừng và chuyển bạn vào <strong>Dashboard</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Sai thông tin đăng nhập</p><p>Nếu email hoặc mật khẩu không đúng, hệ thống báo: <em>&quot;Email hoặc mật khẩu không đúng. Vui lòng kiểm tra lại.&quot;</em> Kiểm tra lại thông tin và thử lại.</p></div><h3 id="quen-mat-khau" tabindex="-1">Quên mật khẩu <a class="header-anchor" href="#quen-mat-khau" aria-label="Permalink to &quot;Quên mật khẩu&quot;">​</a></h3><ol><li>Tại form đăng nhập, nhấn liên kết <strong>Quên mật khẩu?</strong> (cạnh ô Mật khẩu).</li><li>Cửa sổ <strong>Quên Mật Khẩu?</strong> hiện ra, hướng dẫn liên hệ quản trị viên để được cấp lại mật khẩu.</li><li>Liên hệ qua một trong các kênh hiển thị: <ul><li><strong>Email Quản Trị:</strong> <code>namtp@fadogroup.com.au</code></li><li><strong>Hotline:</strong> <code>0935 29 0953</code></li></ul></li><li>Nhấn <strong>Quay Lại Đăng Nhập</strong> để đóng cửa sổ.</li></ol><div class="info custom-block"><p class="custom-block-title">Vì sao không tự đặt lại?</p><p>Để đảm bảo an toàn, việc cấp lại mật khẩu được thực hiện bởi quản trị viên. Quản trị viên có thể gửi cho bạn một liên kết đặt lại mật khẩu qua email.</p></div><h3 id="đat-lai-mat-khau-qua-lien-ket-email" tabindex="-1">Đặt lại mật khẩu qua liên kết email <a class="header-anchor" href="#đat-lai-mat-khau-qua-lien-ket-email" aria-label="Permalink to &quot;Đặt lại mật khẩu qua liên kết email&quot;">​</a></h3><p>Khi quản trị viên kích hoạt đặt lại mật khẩu, bạn nhận được email chứa liên kết. Liên kết dẫn tới trang <code>/reset-password</code>.</p><ol><li>Mở liên kết trong email. Hệ thống tự <strong>xác minh token</strong> đính kèm.</li><li>Nếu token hợp lệ, trang hiển thị <strong>Đặt Mật Khẩu Mới</strong> kèm email tài khoản của bạn.</li><li>Nhập <strong>Mật Khẩu Mới</strong> (tối thiểu <strong>6 ký tự</strong>) và <strong>Xác Nhận Mật Khẩu</strong>.</li><li>Dùng nút con mắt để kiểm tra mật khẩu đã nhập đúng.</li><li>Nhấn <strong>Cập Nhật Mật Khẩu</strong>.</li><li>Khi thành công, hệ thống tự chuyển về trang đăng nhập sau vài giây.</li></ol><div class="warning custom-block"><p class="custom-block-title">Token hết hạn hoặc không hợp lệ</p><p>Nếu liên kết đã hết hạn hoặc sai, trang báo <strong>Token Không Hợp Lệ</strong>. Hãy yêu cầu quản trị viên gửi lại liên kết mới.</p></div><h3 id="đang-xuat" tabindex="-1">Đăng xuất <a class="header-anchor" href="#đang-xuat" aria-label="Permalink to &quot;Đăng xuất&quot;">​</a></h3><p>Có thể đăng xuất từ hai nơi:</p><ol><li><strong>Menu người dùng</strong> ở góc phải thanh trên cùng (topbar): nhấn avatar/tên → chọn <strong>Đăng Xuất</strong>.</li><li><strong>Cuối thanh điều hướng</strong> (sidebar): nhấn <strong>Đăng Xuất</strong>.</li></ol><p>Sau khi đăng xuất, hệ thống đưa bạn trở về màn hình đăng nhập.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Mật khẩu mới cần dài bao nhiêu?</strong> Tối thiểu 6 ký tự. Nên dùng mật khẩu mạnh, kết hợp chữ và số.</p><p><strong>Tôi không nhận được email đặt lại mật khẩu?</strong> Kiểm tra hộp thư rác. Nếu vẫn không thấy, liên hệ quản trị viên qua email hoặc hotline ở cửa sổ Quên Mật Khẩu.</p><p><strong>Tích &quot;Ghi nhớ đăng nhập&quot; có an toàn không?</strong> Chỉ nên dùng trên thiết bị cá nhân. Trên máy dùng chung, hãy bỏ tích và luôn đăng xuất sau khi dùng.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a> · <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a></p>',28)])])}const d=t(l,[["render",g]]);export{m as __pageData,d as default};
